css:
.bw-future {
  width: 100%;
  height: 100%;
  background: repeating-conic-gradient(
      from 45deg,
      #fff 0deg 10deg,
      #000 10deg 20deg
    ),
    repeating-linear-gradient(90deg, #fff 0px 2px, #000 2px 40px),
    repeating-linear-gradient(0deg, #fff 0px 2px, #000 2px 40px);
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
}

.bw-future::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 200px;
  height: 200px;
  transform: translate(-50%, -50%) rotate(45deg);
  background: repeating-linear-gradient(45deg, #fff 0 10px, #000 10px 20px);
  border: 6px solid #fff;
  box-shadow:
    0 0 40px #fff,
    inset 0 0 20px #fff;
}
